/**
 * The drive connector. Every variable it reads is in README.md, which
 * `lint:config` holds in both directions.
 */
import { createRequire } from 'node:module'
import { boolean, integer, optional, parseGlobs, parseLayerRules, required, runConnector } from '@nacre.work/connector-kit'
import { googleDrive, loadServiceAccountKey } from './google.js'
import { DriveSource } from './source.js'

const { version } = createRequire(import.meta.url)('../package.json') as { version: string }

// Read before anything else, so a key file that is missing or is not a
// service account key refuses the start by name rather than failing the
// first sweep with somebody else's `400`.
const key = loadServiceAccountKey(required('DRIVE_CREDENTIALS'), 'DRIVE_CREDENTIALS')
const subject = process.env['DRIVE_SUBJECT']?.trim() || undefined
const folder = required('DRIVE_FOLDER')
const sharedDrive = boolean('DRIVE_SHARED_DRIVE', false)
const api = optional('DRIVE_API', 'https://www.googleapis.com').replace(/\/+$/, '')
const tokenUrl = optional('DRIVE_TOKEN_URL', 'https://oauth2.googleapis.com/token')
const maxBytes = integer('DRIVE_MAX_BYTES', 10_485_760, { min: 1024 })

await runConnector({
  name: 'drive',
  version,
  source: `${api}/drive/v3/files/${folder}`,
  maxBytes,
  mapping: {
    layer: '${layer}',
    externalId: '${path}',
    title: optional('DRIVE_TITLE', '${name}'),
    content: '${content}',
    metadata: { path: '${path}', ext: '${ext|}', file_id: '${file_id}', mime_type: '${mime_type}' },
  },
  async open() {
    return new DriveSource({
      drive: googleDrive({ key, subject, api, tokenUrl, sharedDrive: sharedDrive ? folder : undefined }),
      folder,
      include: parseGlobs(optional('DRIVE_INCLUDE', '**')),
      exclude: parseGlobs(optional('DRIVE_EXCLUDE', '')),
      rules: parseLayerRules(required('DRIVE_LAYERS'), 'DRIVE_LAYERS'),
      maxBytes,
    })
  },
})

/**
 * The git connector. Every variable it reads is in README.md, which
 * `lint:config` holds in both directions.
 */
import { createRequire } from 'node:module'
import { integer, optional, parseGlobs, parseLayerRules, required, runConnector } from '@nacre.work/connector-kit'
import { GitSource } from './source.js'

const { version } = createRequire(import.meta.url)('../package.json') as { version: string }

const url = required('GIT_URL')
const token = process.env['GIT_TOKEN']
const maxBytes = integer('GIT_MAX_BYTES', 1_048_576, { min: 1024 })

await runConnector({
  name: 'git',
  version,
  source: url,
  maxBytes,
  mapping: {
    layer: '${layer}',
    externalId: '${path}',
    title: optional('GIT_TITLE', '${name}'),
    content: '${content}',
    metadata: { path: '${path}', ext: '${ext|}', ref: optional('GIT_REF', 'HEAD') },
  },
  async open(config) {
    const source = new GitSource({
      url,
      ref: process.env['GIT_REF']?.trim() || undefined,
      dir: optional('GIT_DIR', `${config.statePath.replace(/[^/]*$/, '')}repo.git`),
      include: parseGlobs(optional('GIT_INCLUDE', '**')),
      exclude: parseGlobs(optional('GIT_EXCLUDE', '')),
      rules: parseLayerRules(required('GIT_LAYERS'), 'GIT_LAYERS'),
      maxBytes,
      credential: token === undefined || token === '' ? undefined : { username: optional('GIT_USERNAME', 'x-access-token'), token },
    })
    await source.open()
    return source
  },
})

/**
 * The imap connector. Every variable it reads is in README.md, which
 * `lint:config` holds in both directions.
 */
import { createRequire } from 'node:module'
import { boolean, compile, ConfigError, integer, optional, required, runConnector } from '@nacre.work/connector-kit'
import { imapMailbox } from './imap.js'
import { ImapSource, parseImapUrl, parseSince } from './source.js'

const { version } = createRequire(import.meta.url)('../package.json') as { version: string }

const url = required('IMAP_URL')
const mailbox = parseImapUrl(url)
const since = parseSince(optional('IMAP_SINCE', ''))
// Compiled here so a malformed template is refused by the variable's name;
// the mapping below reads what these render.
const layer = compile(required('IMAP_LAYER'), 'IMAP_LAYER')
const title = compile(optional('IMAP_TITLE', '${subject|(no subject)}'), 'IMAP_TITLE')
const maxBytes = integer('IMAP_MAX_BYTES', 10_485_760, { min: 1024 })

/** `key=template;key=template`, each key one the connector does not already write. */
function parseMetadata(spec: string): Record<string, string> {
  const fixed = new Set(['connector', 'source', 'folder', 'message_id', 'from', 'date', 'filename'])
  const out: Record<string, string> = {}
  for (const part of spec.split(';')) {
    const entry = part.trim()
    if (entry === '') continue
    const eq = entry.indexOf('=')
    if (eq <= 0) throw new ConfigError(`IMAP_METADATA: ${JSON.stringify(entry)} is not key=template`)
    const key = entry.slice(0, eq).trim()
    if (!/^[a-z][a-z0-9_]{0,63}$/.test(key)) throw new ConfigError(`IMAP_METADATA: key ${JSON.stringify(key)} must be lower-case letters, digits and underscores`)
    if (fixed.has(key)) throw new ConfigError(`IMAP_METADATA: ${key} is written by the connector itself; pick another key`)
    compile(entry.slice(eq + 1).trim(), `IMAP_METADATA (${key})`)
    out[key] = entry.slice(eq + 1).trim()
  }
  return out
}

await runConnector({
  name: 'imap',
  version,
  source: url,
  maxBytes,
  mapping: {
    layer: '${layer}',
    externalId: '${id}',
    title: '${title}',
    content: '${text}',
    metadata: {
      folder: '${folder}',
      message_id: '${message_id|}',
      from: '${from|}',
      date: '${date|}',
      filename: '${filename|}',
      ...parseMetadata(optional('IMAP_METADATA', '')),
    },
  },
  async open() {
    return new ImapSource({
      mailbox: imapMailbox(mailbox),
      folder: mailbox.folder,
      since,
      layer,
      title,
      attachments: boolean('IMAP_ATTACHMENTS', true),
      maxBytes,
    })
  },
})

/**
 * The mongo connector. Every variable it reads is in README.md, which
 * `lint:config` holds in both directions.
 */
import { createRequire } from 'node:module'
import { compile, ConfigError, integer, optional, required, runConnector } from '@nacre.work/connector-kit'
import { mongoCollection, parseUrl } from './driver.js'
import { MongoSource, parseJsonObject, parseMetadata, parsePath, parseProjection } from './source.js'

const { version } = createRequire(import.meta.url)('../package.json') as { version: string }

/** A template refused at startup by the variable's name, not by the mapping slot it fills. */
function template(name: string, source: string): string {
  try {
    compile(source, name)
  } catch (e) {
    throw new ConfigError(e instanceof Error ? e.message : String(e))
  }
  return source
}

const url = required('MONGO_URL')
let parsed: ReturnType<typeof parseUrl>
try {
  parsed = parseUrl(url)
} catch (e) {
  throw new ConfigError(`MONGO_URL is not a connection string: ${e instanceof Error ? e.message : String(e)}`)
}
const database = optional('MONGO_DATABASE', parsed.database ?? '')
if (database === '') throw new ConfigError('MONGO_DATABASE is not set and MONGO_URL names no database; one of them has to')
const collection = required('MONGO_COLLECTION')
const filter = parseJsonObject('MONGO_FILTER', optional('MONGO_FILTER', '{}'))
const projectionRaw = process.env['MONGO_PROJECTION']?.trim() || undefined
const projection = projectionRaw === undefined ? undefined : parseProjection('MONGO_PROJECTION', projectionRaw)
const id = parsePath('MONGO_ID', optional('MONGO_ID', '_id'))
const versionRaw = process.env['MONGO_VERSION']?.trim() || undefined
const versionField = versionRaw === undefined ? undefined : parsePath('MONGO_VERSION', versionRaw)
const title = process.env['MONGO_TITLE']?.trim() || undefined
const maxBytes = integer('MONGO_MAX_BYTES', 10_485_760, { min: 1024 })
const metadata = Object.fromEntries(
  Object.entries(parseMetadata('MONGO_METADATA', optional('MONGO_METADATA', ''))).map(([key, source]) => [key, template(`MONGO_METADATA (${key})`, source)]),
)

await runConnector({
  name: 'mongo',
  version,
  source: `${parsed.origin}/${database}/${collection}`,
  maxBytes,
  mapping: {
    layer: template('MONGO_LAYER', required('MONGO_LAYER')),
    externalId: template('MONGO_EXTERNAL_ID', optional('MONGO_EXTERNAL_ID', '${doc_id}')),
    ...(title === undefined ? {} : { title: template('MONGO_TITLE', title) }),
    content: template('MONGO_CONTENT', optional('MONGO_CONTENT', '${content}')),
    // The operator's keys first and the connector's two last, so `collection`
    // and `doc_id` are what their names say on every document.
    metadata: { ...metadata, collection, doc_id: '${doc_id}' },
  },
  async open() {
    let source: ReturnType<typeof mongoCollection>
    try {
      source = mongoCollection({ url, database, collection })
    } catch (e) {
      // The driver refuses a string its grammar admits but it cannot use —
      // an unknown option, a bad escape — and the message names the part,
      // never the string.
      throw new ConfigError(`MONGO_URL: ${e instanceof Error ? e.message : String(e)}`)
    }
    return new MongoSource({ collection: source, filter, projection, id, version: versionField })
  },
})

/**
 * The s3 connector. Every variable it reads is in README.md, which
 * `lint:config` holds in both directions.
 */
import { createRequire } from 'node:module'
import { boolean, ConfigError, integer, optional, parseGlobs, parseLayerRules, required, runConnector } from '@nacre.work/connector-kit'
import { awsStore } from './aws.js'
import { S3Source } from './source.js'

const { version } = createRequire(import.meta.url)('../package.json') as { version: string }

const bucket = required('S3_BUCKET')
const prefix = optional('S3_PREFIX', '').replace(/^\/+/, '')
const endpoint = process.env['S3_ENDPOINT']?.trim() || undefined
const accessKeyId = process.env['S3_ACCESS_KEY_ID']?.trim() || undefined
const secretAccessKey = process.env['S3_SECRET_ACCESS_KEY']?.trim() || undefined
if ((accessKeyId === undefined) !== (secretAccessKey === undefined)) {
  throw new ConfigError('S3_ACCESS_KEY_ID and S3_SECRET_ACCESS_KEY are a pair: set both, or neither and let the AWS credential chain decide')
}
const maxBytes = integer('S3_MAX_BYTES', 10_485_760, { min: 1024 })

await runConnector({
  name: 's3',
  version,
  source: `${endpoint ?? 's3:/'}/${bucket}/${prefix}`,
  maxBytes,
  mapping: {
    layer: '${layer}',
    externalId: '${path}',
    title: optional('S3_TITLE', '${name}'),
    content: '${content}',
    metadata: { path: '${path}', ext: '${ext|}', bucket, key: '${key}' },
  },
  async open() {
    return new S3Source({
      store: awsStore({
        bucket,
        region: optional('S3_REGION', 'us-east-1'),
        endpoint,
        forcePathStyle: boolean('S3_FORCE_PATH_STYLE', false),
        credentials: accessKeyId === undefined || secretAccessKey === undefined ? undefined : { accessKeyId, secretAccessKey },
      }),
      prefix,
      include: parseGlobs(optional('S3_INCLUDE', '**')),
      exclude: parseGlobs(optional('S3_EXCLUDE', '')),
      rules: parseLayerRules(required('S3_LAYERS'), 'S3_LAYERS'),
      maxBytes,
    })
  },
})

/**
 * The sql connector. Every variable it reads is in README.md, which
 * `lint:config` holds in both directions.
 */
import { createRequire } from 'node:module'
import { integer, optional, required, runConnector } from '@nacre.work/connector-kit'
import { driverFor, openQuery } from './db.js'
import { column, parseMetadata, SqlSource } from './source.js'

const { version } = createRequire(import.meta.url)('../package.json') as { version: string }

const url = required('SQL_URL')
driverFor(url)
const statement = required('SQL_QUERY')
const idColumn = column('SQL_ID', optional('SQL_ID', 'id'))
const versionRaw = process.env['SQL_VERSION']?.trim() || undefined
const versionColumn = versionRaw === undefined ? undefined : column('SQL_VERSION', versionRaw)
const maxBytes = integer('SQL_MAX_BYTES', 10_485_760, { min: 1024 })

await runConnector({
  name: 'sql',
  version,
  source: url,
  maxBytes,
  mapping: {
    layer: required('SQL_LAYER'),
    externalId: optional('SQL_EXTERNAL_ID', `\${${idColumn}}`),
    title: optional('SQL_TITLE', '${title}'),
    content: optional('SQL_CONTENT', '${content}'),
    metadata: { ...parseMetadata(optional('SQL_METADATA', ''), 'SQL_METADATA'), row_id: `\${${idColumn}}` },
  },
  async open() {
    return new SqlSource({ query: openQuery(url, statement), idColumn, versionColumn })
  },
})
